W_RANGE.source_excerpt:
if (alloc_fire) assert(alloc_entry < 9);
if (retire_fire) assert(retire_entry < 9);
if (issue_success) assert(issue_entry < 9);
if (capture_valid) assert(capture_entry < 9);

WRAPPER.source_excerpt:
always @(posedge clk) begin
    f_started <= 1;
    if (!f_started) assume(!rst_n);
    else assume(rst_n);
    if(arvalid) begin
        assume(src < 3);
        assume(arresp == 2'b00 || arresp == 2'b11);
    end
    if(arready == 0) assume(!arvalid);
end

T_DELAY.source_excerpt:
    assert(ret_valid_q[0]==$past(issue_success));
    if(ret_valid_q[0]) assert(ret_entry_q[0]==$past(issue_entry));
end
if(f_delay_history[1]) begin
    assert(ret_valid_q[1]==$past(issue_success,2));
    if(ret_valid_q[1]) assert(ret_entry_q[1]==$past(issue_entry,2));
end
if(f_delay_history[2]) begin
    assert(ret_valid_q[2]==$past(issue_success,3));
    if(ret_valid_q[2]) assert(ret_entry_q[2]==$past(issue_entry,3));
end
if(f_delay_history[3]) begin
    assert(capture_valid==$past(issue_success,4));
    if(capture_valid) assert(capture_entry==$past(issue_entry,4));
end else assert(!capture_valid);

O_ISSUE.source_excerpt:
A_ORDER_ISSUE_VALID: assert(issue_valid_q == fo_issue_valid_q);
A_ORDER_ISSUE_SUCCESS: assert(issue_success == fo_success);
if (fo_issue_valid_q) begin
    A_ORDER_ISSUE_ID: assert(issue_entry == fo_issue_entry_q);

O_SELECT.source_excerpt:
A_ORDER_SELECT_VALID: assert(select_valid == fo_select_valid);
if (fo_select_valid)
    A_ORDER_SELECT_ID: assert(select_entry == fo_select_entry);

C_ALL_EVENTS.source_excerpt:
C_ORDER_ALL_PIPELINE_BOUNDARIES:
    cover(fo_accept && fo_select_valid && fo_success &&
          fo_capture && fo_retire);

C_FULL_REUSE.source_excerpt:
C_ORDER_FULL_REUSE:
    cover(fo_count_q == 9 && fo_accept && fo_retire &&
          alloc_entry == fo_retire_entry);

C_SEVEN_REFILL.source_excerpt:
C_ORDER_SEVEN_SOURCE_REFILL:
    cover(fo_occ[0] == 7 && fo_retire && fo_winner == 0 &&
          fo_accept && src == 0);
